def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_threat = 0
    desperate_opp = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_threat += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0)))
                except Exception:
                    pass

    if not alive:
        return float(min(budget, 18.0 if hp > 3 else 40.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if supply <= 17:
        urgency += 2
    elif supply <= 19:
        urgency += 1

    urgency += min(2, desperate_opp)

    if day >= 8 and hp <= 5:
        urgency += 1

    if highest_prev >= 130:
        pressure_mode = 'extreme'
    elif highest_prev >= 90:
        pressure_mode = 'high'
    elif highest_prev >= 50:
        pressure_mode = 'medium'
    else:
        pressure_mode = 'low'

    if urgency >= 6:
        bid = max(95.0, highest_prev + 2.5)
    elif urgency >= 4:
        if pressure_mode == 'extreme':
            bid = 88.0
        elif pressure_mode == 'high':
            bid = max(72.0, avg_prev + 3.0)
        else:
            bid = max(58.0, highest_prev + 2.0)
    elif urgency >= 2:
        if supply >= 22:
            bid = 26.0
        elif pressure_mode == 'extreme':
            bid = 22.0
        elif pressure_mode == 'high':
            bid = 38.0
        else:
            bid = max(28.0, avg_prev * 0.75)
    else:
        if supply >= 22:
            bid = 14.0
        elif supply >= 20:
            bid = 18.0
        elif pressure_mode == 'extreme':
            bid = 16.0
        else:
            bid = 22.0

    if rich_threat >= 2 and urgency >= 4:
        bid += 6.0
    if rich_threat >= 2 and urgency <= 1:
        bid -= 3.0

    reserve = 0.0
    if day <= 3:
        reserve = 25.0
    elif day <= 6:
        reserve = 18.0
    else:
        reserve = 8.0

    max_affordable = max(0.0, budget - reserve)
    if urgency >= 5:
        max_affordable = budget

    bid = min(bid, max_affordable if max_affordable > 0 else budget)

    floor_bid = 0.0
    if urgency >= 4:
        floor_bid = 40.0
    elif urgency >= 2:
        floor_bid = 20.0
    elif supply <= 17:
        floor_bid = 12.0

    bid = max(floor_bid, bid)
    bid = min(bid, budget)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.2)

    base_bid = DAILY_SALARY * 0.65

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.85
    elif my_no_water_days > 0:
        base_bid = DAILY_SALARY * 0.75

    normalized_supply = (current_supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    scarcity_factor = 1 - normalized_supply
    base_bid += (DAILY_SALARY * 0.2) * scarcity_factor

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.7:
            if my_hp <= 4:
                base_bid = max(base_bid, highest_prev_bid * 1.05)
            else:
                base_bid = max(base_bid, highest_prev_bid * 1.01)
        elif highest_prev_bid > base_bid * 0.7:
            base_bid = max(base_bid, highest_prev_bid + 1.0)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        if my_budget > DAILY_SALARY * 1.5:
            base_bid = max(base_bid, DAILY_SALARY * 0.9)
        elif my_hp <= 3:
            base_bid = DAILY_SALARY * 0.99

    final_bid = min(my_budget, base_bid)

    return max(1.0, final_bid)

